    date: '2021-12-31',
    summary: 'opengauss数据库-高可用jdbc使用方法',
    archives: '2021-12',
    img: '/zh/blogs/2022/title/img20.png',
    articleName: 'opengauss数据库-高可用jdbc使用方法.md',
    author: ['周琦放'],
    textContent:
      'opengauss 数据库-高可用 jdbc 使用方法 驱动下载 下载 jdbc 驱动 openGauss-2.1.0-JDBC.tar.gz 下载地址：https://opengauss.org/zh/download/ 表 demo 案例 create database test;\ncreate schema demo;\nCREATE TABLE demo.websites (\n  id int NOT NULL,\n  name char(20) NOT NULL DEFAULT \'\',\n  url varchar(255) NOT NULL DEFAULT \'\',\n  PRIMARY KEY (id)\n);\nCOMMENT ON COLUMN demo.websites.name IS \'站点名称\';\nINSERT INTO demo.websites VALUES\n\n(\'1\', \'openGauss\', \'https://opengauss.org/zh/\'),\n(\'2\', \'华为云\', \'https://www.huaweicloud.com/\'),\n(\'3\', \'openEuler\', \'https://openeuler.org/zh/\'),\n(\'4\', \'华为support中心\', \'https://support.huaweicloud.com/\');\n vip 使用方法 请注意 ..***.***29 为 mogha 组件中的 vip 地址 package com.company;\nimport java.sql.*;\n\npublic class openGaussSelect {\n    static final String JDBC_DRIVER = "org.postgresql.Driver";\n    static final String DB_URL = "jdbc:postgresql://***.***.***.***29:26000/test";\n    // 数据库的用户名与密码，需要根据自己的设置\n    static final String USER = "test";\n    static final String PASS = "zhou0815FANG";\n    public static void main(String[] args) {\n        Connection conn = null;\n        Statement stmt = null;\n        try{\n            // 注册 JDBC 驱动\n            Class.forName(JDBC_DRIVER);\n            // 打开链接\n            System.out.println("连接数据库...");\n            conn = DriverManager.getConnection(DB_URL,USER,PASS);\n\n            // 执行查询\n            System.out.println(" 实例化Statement对象...");\n            stmt = conn.createStatement();\n            String sql;\n            sql = "SELECT id, name, url FROM demo.websites";\n            ResultSet rs = stmt.executeQuery(sql);\n            // 展开结果集数据库\n            while(rs.next()){\n                // 通过字段检索\n                int id  = rs.getInt("id");\n                String name = rs.getString("name");\n                String url = rs.getString("url");\n                // 输出数据\n                System.out.print("ID: " + id);\n                System.out.print(", 站点名称: " + name);\n                System.out.print(", 站点 URL: " + url);\n                System.out.print("\\n");\n            }\n            // 完成后关闭\n            rs.close();\n            stmt.close();\n            conn.close();\n        }catch(SQLException se){\n\n            // 处理 JDBC 错误\n            se.printStackTrace();\n        }catch(Exception e){\n            // 处理 Class.forName 错误\n            e.printStackTrace();\n        }finally{\n            // 关闭资源\n            try{\n                if(stmt!=null) stmt.close();\n            }catch(SQLException se2){\n            }// 什么都不做\n            try{\n                if(conn!=null) conn.close();\n            }catch(SQLException se){\n                se.printStackTrace();\n            }\n        }\n        System.out.println("Goodbye!");\n    }\n}\n 测试验证 JDBC 轮询 使用 jdbc 中 targetServerType=master 属性 package com.company;\n\nimport java.sql.*;\npublic class openGaussSelect {\n    static final String JDBC_DRIVER = "org.postgresql.Driver";\n    static final String DB_URL = "jdbc:postgresql://***.***.***.***:26000,***.***.***.***:26000/test?targetServerType=master";\n    // 数据库的用户名与密码，需要根据自己的设置\n    static final String USER = "test";\n    static final String PASS = "zhou0815FANG";\n    public static void main(String[] args) {\n        Connection conn = null;\n        Statement stmt = null;\n        try{\n            // 注册 JDBC 驱动\n            Class.forName(JDBC_DRIVER);\n\n            // 打开链接\n            System.out.println("连接数据库...");\n            conn = DriverManager.getConnection(DB_URL,USER,PASS);\n\n            // 执行查询\n            System.out.println(" 实例化Statement对象...");\n            stmt = conn.createStatement();\n            String sql;\n            sql = "SELECT id, name, url FROM demo.websites";\n            ResultSet rs = stmt.executeQuery(sql);\n\n            // 展开结果集数据库\n            while(rs.next()){\n                // 通过字段检索\n                int id  = rs.getInt("id");\n                String name = rs.getString("name");\n                String url = rs.getString("url")\n\n                // 输出数据\n                System.out.print("ID: " + id);\n                System.out.print(", 站点名称: " + name);\n\n                System.out.print(", 站点 URL: " + url);\n                System.out.print("\\n");\n            }\n            // 完成后关闭\n            rs.close();\n            stmt.close();\n            conn.close();\n        }catch(SQLException se){\n            // 处理 JDBC 错误\n            se.printStackTrace();\n        }catch(Exception e){\n            // 处理 Class.forName 错误\n            e.printStackTrace();\n        }finally{\n            // 关闭资源\n            try{\n                if(stmt!=null) stmt.close();\n            }catch(SQLException se2){\n            }// 什么都不做\n            try{\n                if(conn!=null) conn.close();\n            }catch(SQLException se){\n                se.printStackTrace();\n            }\n        }\n        System.out.println("Goodbye!");\n    }\n}\n 测试验证',
    type: 'blogs',
    title: 'opengauss数据库-高可用jdbc使用方法',
    tags: ['opengauss数据库-高可用jdbc使用方法'],
    path: 'zh/blogs/2022/opengauss数据库-高可用jdbc使用方法',
    times: '12:30',
    lang: 'zh',
    category: 'blog',
